        state = (target_size, tuple(components))
        if state in memo:
            return memo[state]

        if not components:
            return float('inf')

        size = components[-1]
        if size > target_size:
            return float('inf')

        best = float('inf')

        # Try using this component and continue with both options
        for start_idx in range(len(components)):
            # Greedy approach: try to use smallest components first for exact match
            current_sum = size
            for i in range(start_idx, len(components) - 1):
                if current_sum + components[i] == target_size:
                    return 2  # Can form with 2 components, need 1 road
                elif current_sum + components[i] > target_size:
                    break
                current_sum += components[i]

        # Check if we can form exact size using subset
        for i, size_req in enumerate(components):
            if size_req == target_size:
                memo[state] = 1
                return 1
            if size_req > target_size:
                continue

            # For 2 components check
            for j in range(i + 1, len(components)):
                if size_req + components[j] == target_size:
                    memo[state] = 2
                    return 2

        # Try BFS/DFS approach for exact target
        from collections import deque
        queue = deque([0])
        count = {0}

        while queue:
            level_size = len(queue)
            for _ in range(level_size):
                current = queue.popleft()
                if current == target_size:
                    return len(count) - 1  # Number of components needed minus 1 = roads

                # Try adding next available component
                for idx, sz in enumerate(components):
                    if sz <= target_size - current:
                        new_sum = current + sz
                        if new_sum in count:
                            continue
                        if new_sum > target_size:
                            break
                        queue.append(new_sum)
                        count.append(new_sum)
                        memo[state] = len(count) - 1
                        break

        memo[state] = float('inf')
        return float('inf')

    # Check all lucky numbers to find which is cheapest to form
