def solve_graph(n, edges):
    """
    Solve the system of equations.
    Uses a combination of component analysis and constraint propagation.
    """
    # Build adjacency with constraints
    adj = {}
    for u, v, c in edges:
        if u not in adj:
            adj[u] = {}
        if v not in adj:
            adj[v] = {}

    # Use BFS-like propagation
    assignments = {}

    def solve_component(start_node):
        if start_node in assignments:
            return assignments[start_node]

        # DFS to assign values
        stack = [(start_node, 0.0)]
        assignments[start_node] = 0.0

        while stack:
            u, uval = stack.pop()
            neighbors = adj.get(u, {})

            for v, c in neighbors.items():
                if v not in assignments:
                    assignments[v] = c - uval
                    stack.append((v, assignments[v]))
            # Check for cycles
            for v, c in neighbors.items():
                if v in assignments:
                    if abs(assignments[v] - (c - uval)) > 1e-6:
                        return None
        return assignments[start_node]

    # Try to solve
    values = [0.0] * n

    # Group nodes by connected components
    visited = set()
    for node in range(1, n + 1):
        if node not in visited and node in adj:
            comp_values = solve_component(node)
            if comp_values is None:
                return None
            for node_idx, val in comp_values.items():
                values[node_idx-1] = val
            visited.update(comp_values.keys())

    return values
