# Actual solution for testing
def solution_correct(input_str):
    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())
    v = list(map(int, lines[1].split()))
    c = list(map(int, lines[2].split()))

    # For each starting position i, find maximum potential
    # f[i] = max over all j>=i of min(max_v[i..j]*100, min_c[i..j])
    f = [0] * n
    for i in range(n):
        max_v = 0
        min_c = float('inf')
        best_p = 0
        for j in range(i, n):
            max_v = max(max_v, v[j])
            min_c = min(min_c, c[j])
            p = min(max_v * 100, min_c)
            if p > best_p:
                best_p = p
        f[i] = best_p

    # Sort to get order statistics
    f_sorted = sorted(f)

    # Expected minimum of k samples from n values without replacement
    # = sum_i (f_sorted[i] * P(min = f_sorted[i]))
    # P(min = f_sorted[i]) = C(n-i, k) - C(n-i-1, k)) / C(n, k)

    comb_n_k = comb(n, k)
    total = 0.0

    for i in range(n):
        ways = comb(n - i, k) - comb(n - i - 1, k)
        if ways > 0:
            total += f_sorted[i] * ways

    expected = total / comb_n_k
    return f"{expected:.20f}"


