from collections import deque

def solution(grid_str):
    """
    Problem: Given a grid with walls ('*') and free spaces ('.'),
    remove minimum walls so that all rooms (connected free spaces)
    become rectangular.

    Approach:
    1. Find all connected components (rooms) of free spaces
    2. For each room, fill in all cells within its bounding box
       (convert '*' to '.' within the bbox)
    """
    grid_str = grid_str.strip()
    lines = grid_str.split('\n')

    if not lines:
        return ""

    n, m = map(int, lines[0].split())

    # Read grid
    if len(lines) < n + 1:
        # Pad with empty lines if needed
        actual_n = min(n, len(lines) - 1)
        grid = [list(lines[i + 1]) if i + 1 < len(lines) else [] for i in range(actual_n)]
        # Pad rows if needed
        for row in grid:
            while len(row) < m:
                row.append('*')
        return '\n'.join(''.join(row) for row in grid[:n])

    grid = [list(lines[i + 1]) if i + 1 < len(lines) else ['*'] * m for i in range(n)]

    visited = [[False] * m for _ in range(n)]
    rooms = []  # Each room is (r_min, r_max, c_min, c_max, cells)

    # Helper to find the room cells using BFS
    def bfs_room(start_r, start_c):
        cells = []
        queue = deque([(start_r, start_c)])
        visited[start_r][start_c] = True
        cells.append((start_r, start_c))

        while queue:
            r, c = queue.popleft()
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m:
                    if grid[nr][nc] == '.' and not visited[nr][nc]:
                        visited[nr][nc] = True
                        cells.append((nr, nc))
                        queue.append((nr, nc))
        return cells

    # Find all rooms
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.' and not visited[i][j]:
                cells = bfs_room(i, j)
                if cells:
                    r_min = min(r for r, c in cells)
                    r_max = max(r for r, c in cells)
                    c_min = min(c for r, c in cells)
                    c_max = max(c for r, c in cells)
                    rooms.append((r_min, r_max, c_min, c_max))

    # For each room, fill its bounding box with free spaces
    for r_min, r_max, c_min, c_max in rooms:
        for i in range(r_min, r_max + 1):
            for j in range(c_min, c_max + 1):
                if grid[i][j] == '*':
                    grid[i][j] = '.'

    # Convert back to string
    result_lines = [''.join(row) for row in grid]
    return '\n'.join(result_lines)


