        for i in range(1, n + 1):
            fact[i] = (fact[i - 1] * i) % MOD

        inv[n] = pow_mod(fact[n], MOD - 2)
        for i in range(n - 1, -1, -1):
            inv[i] = (inv[i + 1] * (i + 1)) % MOD

        def C(n, k):
            if k < 0 or k > n:
                return 0
            return (fact[n] * inv[k] % MOD) * inv[n - k] % MOD

        def power(a, b):
            return pow_mod(a, b)

        result = 0

        for i in range(1, n + 1):
            term = (power(i, k) * C(n, i - 1)) % MOD
            result = (result + term) % MOD

        return '\n' + str(result) + '\n'
    else:
        # Use the formula derived from combinatorial analysis
        # For larger n, the contribution is computed differently
        result = 0

        for i in range(1, k + 1):
            if i <= n:
                term = (power(i, k) % MOD) * (C_large(n, i - 1) % MOD)
                result = (result + term) % MOD

        return '\n' + str(result % MOD) + '\n'


def C_large(n, r):
    # For very large n, compute C(n,r) using the formula: n*(n-1)*...*(n-r+1)/r!
    MOD = 998244353

    if r < 0 or r > n:
        return 0

    num = 1
    for i in range(r):
        num = (num * ((n - i) % MOD)) % MOD

    denom = 1
    for i in range(1, r + 1):
        denom = (denom * i) % MOD

    return (num * pow_mod(denom, MOD - 2)) % MOD


def pow_mod(a, b):
    result = 1
    a = a % 998244353
    while b > 0:
        if b & 1:
            result = (result * a) % 998244353
        a = (a * a) % 998244353
        b >>= 1
    return result


def solution(input_str):
