def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    min_time = float('inf')

    # Try all possible wave origin positions T from 1 to n
    for T in range(1, n + 1):
        # Calculate when each icicle will fall
        # Icicle at position i falls at time |i - T| + a[i]
        icicle_fall_times = {}
        for i in range(1, n + 1):
            icicle_fall_times[i] = abs(i - T) + a[i-1]

        # Find the maximum fall time we need to consider
        max_fall_time = max(icicle_fall_times.values())

        # Simulate over time
        # Krakozyabra starts at position 1 and moves right at speed 1
        # At time t, Krakozyabra is at position 1 + t

        for t in range(1, max_fall_time + 2):
            krak_pos = 1 + t

            # Check if there are fallen icicles to the left
            fell_left = False
            for i in range(1, krak_pos):
                if i in icicle_fall_times and icicle_fall_times[i] <= t:
                    fell_left = True
                    break

            # Check if there are fallen icicles to the right
            fell_right = False
            for i in range(krak_pos, n + 1):
                if i in icicle_fall_times and icicle_fall_times[i] <= t:
                    fell_right = True
                    break

            if fell_left and fell_right:
                min_time = min(min_time, t)
                break  # Found minimum for this T, move to next T

    if min_time == float('inf'):
        return "-1\n"
    else:
        return f"{min_time}\n"
