def solution(input_str):
    """
    Count the number of squares in a 0-1 matrix.
    A square is a frame with 1s on the border and 0s inside,
    that doesn't touch any foreign 1s.
    """
    lines = input_str.strip().split('\n')
    t = int(lines[0])
    results = []

    idx = 1
    for _ in range(t):
        n, m = map(int, lines[idx].split())
        idx += 1

        matrix = []
        for i in range(n):
            row = [int(c) for c in lines[idx + i]]
            matrix.append(row)
        idx += n

        count = 0

        # Check axis-aligned squares
        for size in range(2, min(n, m) + 1):
            for r in range(n - size + 1):
                for c in range(m - size + 1):
                    valid = True

                    # Check top row (all 1s)
                    for j in range(size):
                        if matrix[r][c + j] != 1:
                            valid = False
                            break
                    if not valid:
                        continue

                    # Check bottom row (all 1s)
                    for j in range(size):
                        if matrix[r + size - 1][c + j] != 1:
                            valid = False
                            break
                    if not valid:
                        continue

                    # Check interior column (all 1s for axis-aligned)
                    for i in range(1, size - 1):
                        if matrix[r + i][c] != 1:
                            valid = False
                            break
                    if not valid:
                        continue

                    # Check interior column right side (all 1s for axis-aligned)
                    for i in range(1, size - 1):
                        if matrix[r + i][c + size - 1] != 1:
                            valid = False
                            break
                    if not valid:
                        continue

                    # Interior should be all 0s
                    if size >= 3:
                        for i in range(1, size - 1):
                            for j in range(1, size - 1):
                                if matrix[r + i][c + j] != 0:
                                    valid = False
                                    break
                            if not valid:
                                break
                    if not valid:
                        continue

                    # Check no foreign 1s adjacent (8 directions from every border cell)
                    ok = True
                    for dr in range(-1, 2):
                        for dc in range(-1, 2):
                            if dr == 0 and dc == 0:
                                continue
                            nr, nc = r + dr, c + dc
                            if not (0 <= nr < n and 0 <= nc < m):
                                continue
                            if matrix[nr][nc] != 0:
                                ok = False
                                break
                        if not ok:
                            break

                    if ok:
                        count += 1

        # Check diagonal squares (diamond shape)
        # Size k determines diamond dimensions
        for k in range(2, min(n, m) // 2 + 2):
            for cr in range(k, n - k + k):
                for cc in range(k, m - k + k):
                    diamond_points = []

                    # Calculate top corner
                    if k % 2 == 0:
                        top_r = cr - k + 1
                        top_c = cc
                    else:
                        top_r = cr - (k - 1) // 2
                        top_c = cc

                    # Calculate bottom corner
                    if k % 2 == 0:
                        bot_r = cr + k - 1
                        bot_c = cc
                    else:
                        bot_r = cr + (k - 1) // 2
                        bot_c = cc

                    # Calculate left corner
                    left_r = cr - (k - 1) // 2
                    left_c = cc - (k - 1) // 2

                    # Calculate right corner
                    right_r = cr - (k - 1) // 2
                    right_c = cc + (k - 1) // 2

                    # Add all unique border points
                    top = (top_r, top_c)
                    bottom = (bot_r, bot_c)
                    left = (left_r, left_c)
                    right = (right_r, right_c)

                    # Top edge (left to right)
                    for i in range(k):
                        t_step = (top_r - left_r) * i // (k - 1) if k > 1 else 0
                        l_step = (top_c - left_c) * i // (k - 1) if k > 1 else 0
                        diamond_points.append((top_r - t_step, left_c + l_step))

                    # Bottom edge (right to left)
                    for i in range(k):
                        br = (bot_r - right_r) * (k - 1 - i) // (k - 1)
                        bc = (bot_c - right_c) * (k - 1 - i) // (k - 1)
                        diamond_points.append((right_r + br, right_c - bc))

                    # Left edge (top to bottom)
                    if left != left and left.r != bot_r:
                        for i in range(k):
                            lr = (left_r - bot_r) * i // (k - 1) if k > 1 else 0
                            lc = (left_c - bot_c) * i // (k - 1) if k > 1 else 0
                            diamond_points.append((left_r + lr, left_c + lc))

                    # Right edge
                    if right != right and right.r != bot_r:
                        for i in range(k):
                            if k > 1:
                                rr = (right_r - bot_r) * i // (k - 1)
                                rc = (right_c - bot_c) * i // (k - 1)
                            else:
                                rr = 0
                                rc = 0
                            diamond_points.append((right_r + rr, right_c + rc))

                    # Deduplicate and get unique border points
                    unique_points = list(set(diamond_points))

                    # Check all border points have 1
                    border_ok = True
                    for pr, pc in unique_points:
                        if not (0 <= pr < n and 0 <= pc < m):
                            border_ok = False
                            break
                        if matrix[pr][pc] != 1:
                            border_ok = False
                            break

                    if not border_ok:
                        continue

                    # Check no foreign 1s adjacent (distance 1 from any border point)
                    no_adjacent_ones = True
                    for pr, pc in unique_points:
                        for dr in range(-1, 2):
                            for dc in range(-1, 2):
                                if dr == 0 and dc == 0:
                                    continue
                                npr, npc = pr + dr, pc + dc
                                if not (0 <= npr < n and 0 <= npc < m):
                                    continue
                                if matrix[npr][npc] != 0:
                                    no_adjacent_ones = False
                                    break
                            if not no_adjacent_ones:
                                break
                        if not no_adjacent_ones:
                            break

                    if no_adjacent_ones:
                        count += 1

        results.append(str(count))

    return '\n'.join(results)
