# main solution after all hacks
def solution(input_data):
    lines = input_data.strip().split('\n')
    n, q = map(int, lines[0].split())
    p = list(range(1, n + 1))
    inv = 0
    res = []

    for i in range(1, q + 1):
        l, r = map(int, lines[i].split())
        if l == r or l > r:
            l, r = r, l
            continue
        a, b = p[l-1], p[r-1]
        if a > b:
            change = 1 - sum(1 if min(a,b) <= p[k] <= max(a,b) else 0 for k in range(l, r))
            inv += change
        else:
            change = -1 - sum(1 if min(a,b) <= p[k] <= max(a,b) else 0 for k in range(l, r))
            inv += change
        p[l-1], p[r-1] = p[r-1], p[l-1]
        res.append(str(inv))
    return '\n'.join(res) + '\n'
